Lemma ImplBlock_reindex : forall LB LB' m b I,
  ImplBlock LB m b I ->
  (forall p, In (p, b, SZ_SPCI_IMPL) LB -> In (p, b, SZ_SPCI_IMPL) LB') ->
  (forall q, 0 < im_vcap I -> In (q, im_vb I, 8 * im_vcap I) LB -> In (q, im_vb I, 8 * im_vcap I) LB') ->
  ImplBlock LB' m b I.
Proof.
  intros LB LB' m b I (p & j7 & IN & RB & CH & OK & EV & PM & CV & LE & ST) HB HV. exists p, j7.
  split; [apply HB; exact IN|]. repeat (split; [assumption|]).
  destruct ST as [ST|(q & junk & INq & RBq & POS & R)]; [left; exact ST| right]. exists q, junk.
  split; [apply HV; [exact POS| exact INq]| split; [exact RBq| split; [exact POS| exact R]]].
Qed.

(* [comment removed for export] *)
Lemma xpres_of_rheap_pres_sub : forall LB LB' SP X m m',
  rheap_pres LB' SP m m' ->
  (forall b, In b LB -> In b LB' \/ (forall a, blk_addr b <= a < blk_addr b + blk_size b -> rin_ivs X a)) ->
  xpres LB SP X m m'.
Proof.
  intros LB LB' SP X m m' PRES HX a Ha [HC NX]. apply PRES; [exact Ha|].
  destruct HC as [K|[K|(b & Hb & K)]]; [left; exact K| right; left; exact K|].
  destruct (HX b Hb) as [Hb'|COV]; [right; right; exists b; split; [exact Hb'| exact K]|].
  exfalso. apply NX. apply COV. exact K.
Qed.

