(* [comment removed for export] *)
Definition scs_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (stb u lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 stb) (Z_to_bv 64 312) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPDEL2) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (stb, stb + 32)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' stb (SpcHdrCells (mkSPC VP_SPCI_STATE u 0 0) j7).

Lemma scs_segB : forall (rax : word) sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (ra s0 s1 s2 : word) (F : bvmap 5 word) fc (m : mem) (stb u lo : Z) (j7 : list byte),
