Definition P_BSD_CALL1 : Z := 0x2c8f0.   (* [comment removed for export] *)
Definition P_BSD_RET1  : Z := 0x2c8f4.   (* [comment removed for export] *)
Definition P_BSD_RET2  : Z := 0x2c90c.   (* [comment removed for export] *)

(* [comment removed for export] *)
Definition bsd_seg0_post (sp gp tp t0 t1 t2 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (bs lo : Z) (ra s0 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
    ms' = MS (mkR (Z_to_bv 64 P_BSD_RET1) (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 (Z_to_bv 64 bs) s1 (Z_to_bv 64 bs) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_STREAM_CLOSE) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp + -16)
    /\ rw_cells usegs m' (bv_unsigned sp + -16) [C8 s0; C8 ra].

