(* [comment removed for export] *)
Definition bsd_seg3_post (sp gp tp t0 t1 t2 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (bs lo : Z) (ra s0 : word) (m : mem) : machine_state -> Prop :=
  fun ms' =>
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (bs + 8)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_SHCOUNT_DTOR) fc None m (seg_rom usegs)
    /\ munch [] m m /\ wmono usegs m m /\ mem_inv usegs m
    /\ stk usegs m lo (bv_unsigned sp).

Lemma bsd_seg3 : forall (rax : word) sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (ra s0 : word) (F : bvmap 5 word) fc (m : mem) (bs stb lo : Z),
  rw_cells usegs m bs (BasicStreamCells stb) -> bv_unsigned sp <= bs -> bs + 32 <= 2^64 ->
  rw_cells usegs m (bv_unsigned sp + -16) [C8 s0; C8 ra] ->
  stk usegs m lo (bv_unsigned sp + -16) -> lo + 16 <= bv_unsigned sp ->
  mem_inv usegs m ->
  evt usegs (bsd_seg3_post sp gp tp t0 t1 t2 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc bs lo ra s0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp t0 t1 t2 (Z_to_bv 64 bs) s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_BSD_RET2) fc None m (seg_rom usegs)).
